      writeValue(buffer, value.index);
    } else if (value is InitializeRequestMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is SessionMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is CardMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
